from __future__ import annotations

import subprocess
from pathlib import Path


def _run(*argv: str) -> None:
    result = subprocess.run(
        argv,
        stdin=subprocess.DEVNULL,
        capture_output=True,
        timeout=60,
        check=False,
    )
    if result.returncode != 0:
        raise RuntimeError(result.stderr.decode("utf-8", "replace"))


def generate_probe_fixtures(root: Path, ffmpeg: Path) -> dict[str, Path]:
    root.mkdir(parents=True, exist_ok=True)
    baseline = root / "baseline ü space.mp4"
    _run(
        str(ffmpeg),
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-f",
        "lavfi",
        "-i",
        "color=c=blue:s=320x240:r=30000/1001:d=1",
        "-f",
        "lavfi",
        "-i",
        "sine=f=1000:r=48000:d=1",
        "-map",
        "0:v",
        "-map",
        "1:a",
        "-c:v",
        "libx264",
        "-pix_fmt",
        "yuv420p",
        "-c:a",
        "aac",
        str(baseline),
    )
    video_only = root / "video-only.mov"
    _run(
        str(ffmpeg),
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-f",
        "lavfi",
        "-i",
        "color=c=blue:s=320x240:r=30:d=1",
        "-c:v",
        "libx264",
        "-pix_fmt",
        "yuv420p",
        str(video_only),
    )
    rotated = root / "rotated.mov"
    _run(
        str(ffmpeg),
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-display_rotation:v:0",
        "90",
        "-i",
        str(baseline),
        "-map",
        "0",
        "-c",
        "copy",
        str(rotated),
    )
    black = root / "interior-black.mp4"
    _run(
        str(ffmpeg),
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-f",
        "lavfi",
        "-i",
        "color=c=blue:s=320x240:r=30:d=1",
        "-f",
        "lavfi",
        "-i",
        "color=c=black:s=320x240:r=30:d=2",
        "-f",
        "lavfi",
        "-i",
        "color=c=blue:s=320x240:r=30:d=1",
        "-filter_complex",
        "[0:v][1:v][2:v]concat=n=3:v=1:a=0",
        "-c:v",
        "libx264",
        "-pix_fmt",
        "yuv420p",
        str(black),
    )
    tail = root / "black-tail-15.mp4"
    _run(
        str(ffmpeg),
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-f",
        "lavfi",
        "-i",
        "color=c=blue:s=320x240:r=30:d=1",
        "-f",
        "lavfi",
        "-i",
        "color=c=black:s=320x240:r=30:d=0.5",
        "-filter_complex",
        "[0:v][1:v]concat=n=2:v=1:a=0",
        "-c:v",
        "libx264",
        "-pix_fmt",
        "yuv420p",
        str(tail),
    )
    damaged = root / "damaged-black.mp4"
    _run(
        str(ffmpeg),
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-i",
        str(black),
        "-map",
        "0:v:0",
        "-c:v",
        "copy",
        "-bsf:v",
        "noise=amount=100",
        "-movflags",
        "+faststart",
        str(damaged),
    )
    silence = root / "interior-silence.mov"
    _run(
        str(ffmpeg),
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-f",
        "lavfi",
        "-i",
        "color=c=blue:s=320x240:r=30:d=6",
        "-f",
        "lavfi",
        "-i",
        "sine=f=1000:r=48000:d=1",
        "-f",
        "lavfi",
        "-i",
        "anullsrc=r=48000:cl=mono:d=3",
        "-f",
        "lavfi",
        "-i",
        "sine=f=1000:r=48000:d=2",
        "-filter_complex",
        "[1:a][2:a][3:a]concat=n=3:v=0:a=1[a]",
        "-map",
        "0:v",
        "-map",
        "[a]",
        "-c:v",
        "libx264",
        "-pix_fmt",
        "yuv420p",
        "-c:a",
        "pcm_s16le",
        str(silence),
    )
    active = root / "active-left.mov"
    _run(
        str(ffmpeg),
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-f",
        "lavfi",
        "-i",
        "color=c=blue:s=320x240:r=30:d=3",
        "-f",
        "lavfi",
        "-i",
        "sine=f=1000:r=48000:d=3",
        "-f",
        "lavfi",
        "-i",
        "anullsrc=r=48000:cl=mono:d=3",
        "-filter_complex",
        "[1:a][2:a]join=inputs=2:channel_layout=stereo[a]",
        "-map",
        "0:v",
        "-map",
        "[a]",
        "-c:v",
        "libx264",
        "-pix_fmt",
        "yuv420p",
        "-c:a",
        "pcm_s16le",
        str(active),
    )
    return {
        "baseline": baseline,
        "video_only": video_only,
        "rotated": rotated,
        "interior_black": black,
        "black_tail": tail,
        "damaged": damaged,
        "interior_silence": silence,
        "active_left": active,
    }
